/// Bilance-style Dashboard preview, on the user's REAL computed Revolut data.
///
/// This is a design/layout preview (Bilance = layout reference). It uses a
/// local PURPLE palette to match the Bilance clone — Vaultie's own palette is
/// decided later by the designer. Numbers are computed offline from
/// revolut_txns.json and embedded as base64 JSON (see tools/gen_dash.py).
///
///   flutter run -t lib/main_preview.dart -d <simulator-id>

// ── Vaultie preview palette — light + Charcoal dark (runtime-switchable) ─────
// Brand + semantic colours stay constant across themes.
// Brand accent. Frost = an electric royal blue (was violet). Named `_purple`
// for historical reasons — it's the single accent used across the app.
const _purple = Color(0xFF2F6BFF);
const _purpleDeep = Color(0xFF1E50C8);
const _good = Color(0xFF2FA34E);

// Theme-dependent tokens: reassigned by _applyTheme; _themeVN drives rebuilds.
final ValueNotifier<bool> _themeVN = ValueNotifier<bool>(false);
bool _darkMode = false;

// Set by the live dashboard; a transaction-detail/edit screen calls this after
// mutating the shared `_d['all']` list so totals recompute and data persists.
void Function()? _dashRefresh;
// Defaults = the light "Frost" palette (the primary look): a soft airy page
// with dark ink, so text is always legible.
Color _bg = const Color(0xFFEEF1F7);
Color _purpleSoft = const Color(0xFFE4EDFD);
Color _muted = const Color(0xFF5C6A85); // secondary text — readable on light
Color _faint = const Color(0xFF7C879E); // captions — lighter, still legible
Color _ink = const Color(0xFF14203A);
Color _navOff = const Color(0xFF97A2B5);
Color _card = const Color(0xFFFFFFFF); // card / surface background
Color _hair = const Color(0xFFE3E9F2); // hairline / dividers
Color _soft = const Color(0xFFEEF2F8); // recessed surface (input / inner boxes)

void _applyTheme(bool dark) {
  _darkMode = dark;
  // Light = "Frost". Dark = near-black, back from before e07d9db, but with the
  // surfaces lifted: the old #16121F card sat at 1.07:1 against its own
  // background, so blocks had no edge and the dividers between rows were
  // invisible. Every pair below was solved for a target ratio rather than
  // eyeballed — text ≥ 4.5:1, block edges ≥ 1.25:1, dividers ≥ 1.3:1.
  _bg         = dark ? const Color(0xFF0A0910) : const Color(0xFFEEF1F7);
  _purpleSoft = dark ? const Color(0xFF1B2A55) : const Color(0xFFE4EDFD);
  _muted      = dark ? const Color(0xFFBDB7CE) : const Color(0xFF5C6A85);
  _faint      = dark ? const Color(0xFF948DAC) : const Color(0xFF7C879E);
  _ink        = dark ? const Color(0xFFEDEAF6) : const Color(0xFF14203A);
  _navOff     = dark ? const Color(0xFF8C86A0) : const Color(0xFF97A2B5);
  _card       = dark ? const Color(0xFF262436) : const Color(0xFFFFFFFF);
  _hair       = dark ? const Color(0xFF3D3951) : const Color(0xFFE3E9F2);
  _soft       = dark ? const Color(0xFF0A0912) : const Color(0xFFEEF2F8);
  _themeVN.value = dark;
}

