  Widget _weekSection() {
    // When a filter is active, recompute the week chart from the filtered rows
    // so it stays consistent with the filtered feed and headers.
    // `_d['week']` is null when the account has no transactions in the window —
    // fall back to computing an (empty) week so the home never crashes.
    final week = _txFilter.active
        ? _computeWeek(_feedAll.toList())
        : (_d['week'] as Map<String, dynamic>?) ?? _computeWeek(_feedAll.toList());
    final days = (week['days'] as List).cast<Map<String, dynamic>>();
    final total = (week['total'] as num).toDouble();
    double maxV = 1;
    for (final d in days) {
      final t = (d['total'] as num).toDouble();
      if (t > maxV) maxV = t;
    }
    // Average per ELAPSED day: the week is usually still in progress, so dividing
    // by 7 would understate it. Find this week's Monday (from the range the
    // computed week carries, else the current week) and divide by the days that
    // have actually happened — "your typical day so far". A fully past week
    // divides by 7.
    final n = DateTime.now();
    final today = DateTime(n.year, n.month, n.day);
    DateTime? monday;
    final range = week['range'] as String?;
    if (range != null && range.contains('..')) {
      monday = DateTime.tryParse(range.split('..').first);
    }
    monday ??= today.subtract(Duration(days: today.weekday - 1));
    final sunday = monday.add(const Duration(days: 6));
    final int elapsed = today.isAfter(sunday)
        ? 7
        : today.isBefore(monday)
            ? 1
            : today.difference(monday).inDays + 1;
    final avg = total / elapsed;
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(20, 6, 20, 8),
          child: Row(crossAxisAlignment: CrossAxisAlignment.end, children: [
            Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(tr('Šios savaitės išlaidos'), style: TextStyle(fontSize: 14.5, color: _muted, fontWeight: FontWeight.w500)),
              // Average lives in the header (never on top of a bar or its number).
              if (avg > 0)
                Padding(
                  padding: const EdgeInsets.only(top: 2),
                  child: Text('${tr('vidurkis')} ${avg.round()} €/d.',
                      style: TextStyle(fontSize: 12, color: _faint, fontWeight: FontWeight.w600)),
                ),
            ]),
            const Spacer(),
            // Positive amount — consistent with the month header's "Išleista X".
            Text(_eur(total), style: TextStyle(fontSize: 15, fontWeight: FontWeight.w700, color: _ink)),
          ]),
        ),
        Container(
          margin: const EdgeInsets.fromLTRB(16, 0, 16, 16),
          padding: const EdgeInsets.fromLTRB(10, 16, 10, 10),
          decoration: BoxDecoration(
            color: _bg,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: _hair),
          ),
          child: LayoutBuilder(
            builder: (context, c) {
              final w = c.maxWidth;
              final sel = _weekSel;
              return Stack(
                clipBehavior: Clip.none,
                children: [
                  // € gridlines + average line, BEHIND the bars.
                  Positioned.fill(
                    child: IgnorePointer(
                      child: CustomPaint(
                        painter: _WeekAvgPainter(
                          avg: avg, maxV: maxV, barMax: 118,
                          label: 'vidurkis ${avg.round()} €/d.',
                          dark: _darkMode,
                        ),
                      ),
                    ),
                  ),
                  SizedBox(
                    height: 168,
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.end,
                      children: [
                        for (var i = 0; i < days.length; i++) _bar(days[i], maxV, i),
                      ],
                    ),
                  ),
                  if (sel != null)
                    Positioned(
                      left: ((sel + 0.5) / days.length * w - 110).clamp(0.0, (w - 220).clamp(0.0, double.infinity)),
                      top: -102,
                      child: _weekTip(days[sel]),
                    ),
                ],
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _bar(Map<String, dynamic> d, double maxV, int i) {
    final cats = (d['cats'] as List).cast<Map<String, dynamic>>();
    final tot = (d['total'] as num).toDouble();
    final h = tot > 0 ? (tot / maxV * 118).clamp(3.0, 118.0) : 2.0;
    final selected = _weekSel == i;
    return Expanded(
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () => setState(() => _weekSel = selected ? null : i),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.end,
          children: [
            Text(tot > 0 ? '${tot.round()}€' : '',
                style: TextStyle(fontSize: 11.5, fontWeight: FontWeight.w700, color: selected ? _purple : _muted)),
            const SizedBox(height: 8),
            Opacity(
              opacity: (_weekSel == null || selected) ? 1 : 0.4,
              child: ClipRRect(
                borderRadius: BorderRadius.circular(9),
                child: SizedBox(
                  width: 15,
                  height: h,
                  child: tot > 0
                      ? Column(
                          verticalDirection: VerticalDirection.up,
                          children: [
                            for (final ct in cats)
                              Container(
                                  height: (ct['amount'] as num).toDouble() / tot * h,
                                  color: _secColor[ct['color']] ?? _muted),
                          ],
                        )
                      : Container(color: const Color(0xFFDDE0DD)),
                ),
              ),
            ),
            const SizedBox(height: 9),
            Text(d['lbl'] as String,
                style: TextStyle(
                    fontSize: 12,
                    color: selected ? _purple : _muted,
                    fontWeight: selected ? FontWeight.w700 : FontWeight.w500)),
          ],
        ),
      ),
    );
  }

