// The manual-entry form (amount + category + date + note). Also used to EDIT an
// existing transaction when [initial] is passed (prefills the fields).
class _ManualTxScreen extends StatefulWidget {
  const _ManualTxScreen({required this.kind, this.initial});
  final String kind; // 'expense' | 'income' | 'transfer'
  final Map<String, dynamic>? initial; // when set → edit mode
  @override
  State<_ManualTxScreen> createState() => _ManualTxScreenState();
}

class _ManualTxScreenState extends State<_ManualTxScreen> {
  final _amountCtl = TextEditingController();
  final _noteCtl = TextEditingController();
  late _ManualCat _cat = _catsFor(widget.kind).first;
  late DateTime _date = _today();
  bool get _isEdit => widget.initial != null;

  @override
  void initState() {
    super.initState();
    final init = widget.initial;
    if (init == null) return;
    final a = (init['a'] as num?)?.toDouble() ?? 0;
    if (a != 0) {
      final abs = a.abs();
      _amountCtl.text = abs == abs.roundToDouble() ? abs.toStringAsFixed(0) : abs.toStringAsFixed(2);
    }
    final cats = _catsFor(widget.kind);
    _cat = cats.firstWhere((c) => c.cat == init['cat'], orElse: () => cats.first);
    final d = init['d'] as String?;
    if (d != null) {
      final dt = DateTime.tryParse(d);
      if (dt != null) _date = DateTime(dt.year, dt.month, dt.day);
    }
    // Prefill the note with the merchant name unless it's just the category label.
    final nm = init['nm'] as String?;
    if (nm != null && nm.trim().isNotEmpty && nm != init['cat']) _noteCtl.text = nm;
  }

  static DateTime _today() {
    final n = DateTime.now();
    return DateTime(n.year, n.month, n.day);
  }

  double get _amount {
    final raw = _amountCtl.text.trim().replaceAll(',', '.').replaceAll('€', '').replaceAll(' ', '');
    return double.tryParse(raw) ?? 0;
  }

  bool get _valid => _amount > 0;

  @override
  void dispose() {
    _amountCtl.dispose();
    _noteCtl.dispose();
    super.dispose();
  }

  Future<void> _pickCat() async {
    final cats = _catsFor(widget.kind);
    final picked = await showModalBottomSheet<_ManualCat>(
      context: context,
      backgroundColor: _card,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(20))),
      builder: (_) => SafeArea(
        child: ConstrainedBox(
          constraints: BoxConstraints(maxHeight: MediaQuery.of(context).size.height * 0.7),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const SizedBox(height: 10),
              Container(width: 40, height: 4, decoration: BoxDecoration(color: _faint, borderRadius: BorderRadius.circular(2))),
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 14, 20, 6),
                child: Align(alignment: Alignment.centerLeft, child: Text(tr('Kategorija'), style: TextStyle(fontSize: 18, fontWeight: FontWeight.w800, color: _ink))),
              ),
              Flexible(
                child: ListView.builder(
                  shrinkWrap: true,
                  itemCount: cats.length,
                  itemBuilder: (_, i) {
                    final c = cats[i];
                    final sel = c.cat == _cat.cat;
                    return InkWell(
                      onTap: () => Navigator.of(context).pop(c),
                      child: Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 9),
                        child: Row(children: [
                          CategoryIcon(icon: _iconOf(c.ic), color: _colOf(c.col), size: 40, circle: false),
                          const SizedBox(width: 12),
                          Expanded(
                            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                              Text(tr(c.cat), style: TextStyle(fontSize: 15, fontWeight: FontWeight.w700, color: _ink)),
                              const SizedBox(height: 1),
                              Text(tr(c.sec), style: TextStyle(fontSize: 12, color: _muted)),
                            ]),
                          ),
                          if (sel) const Icon(Icons.check_circle_rounded, color: _purple, size: 22),
                        ]),
                      ),
                    );
                  },
                ),
              ),
              const SizedBox(height: 8),
            ],
          ),
        ),
      ),
    );
    if (picked != null) setState(() => _cat = picked);
  }

  Future<void> _pickDate() async {
    final now = _today();
    final picked = await showDatePicker(
      context: context,
      initialDate: _date,
      firstDate: DateTime(now.year - 3),
      lastDate: now,
      helpText: tr('Data'),
    );
    if (picked != null) setState(() => _date = DateTime(picked.year, picked.month, picked.day));
  }

  void _save() {
    final signed = widget.kind == 'income' ? _amount.abs() : -_amount.abs();
    final note = _noteCtl.text.trim();
    final nm = note.isNotEmpty ? note : _cat.cat;
    final tx = <String, dynamic>{
      'nm': nm,
      'mkey': 'manual-${DateTime.now().microsecondsSinceEpoch}',
      'd': _DashboardPreviewState._ymd(_date),
      // Same date fields bank rows carry, so search/detail don't show "· null".
      'md': '${_monGen[_date.month - 1]} ${_date.day}',
      'wd': const ['Pir', 'Ant', 'Tre', 'Ket', 'Pen', 'Šeš', 'Sek'][_date.weekday - 1],
      'cat': _cat.cat,
      'col': _cat.col,
      'ic': _cat.ic,
      'sec': _cat.sec,
      'secc': _cat.secc,
      'a': double.parse(signed.toStringAsFixed(2)),
      'amb': false,
      'badges': <String>[],
      'pos': signed > 0,
      'count': 0,
      'manual': true,
    };
    Navigator.of(context).pop(tx);
  }

  String get _dateLabel {
    final t = _today();
    if (_date == t) return tr('Šiandien');
    if (_date == t.subtract(const Duration(days: 1))) return tr('Vakar');
    return '${_date.day} ${_monGen[_date.month - 1].toLowerCase()} ${_date.year}';
  }

  @override
  Widget build(BuildContext context) {
    final tint = _kindColor(widget.kind);
    return Scaffold(
      backgroundColor: _bg,
      body: SafeArea(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // header
            Padding(
              padding: const EdgeInsets.fromLTRB(8, 6, 16, 6),
              child: Row(children: [
                IconButton(icon: Icon(Icons.arrow_back_rounded, color: _ink), onPressed: () => Navigator.of(context).pop()),
                Expanded(child: Text(_isEdit ? tr('Redaguoti') : tr(_kindTitle(widget.kind)), style: TextStyle(fontSize: 20, fontWeight: FontWeight.w800, color: _ink))),
              ]),
            ),
            Expanded(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 24),
                children: [
                  // amount
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 22),
                    decoration: BoxDecoration(color: _card, borderRadius: BorderRadius.circular(18), border: Border.all(color: _hair)),
                    child: Row(children: [
                      Text(widget.kind == 'income' ? '+' : '−',
                          style: TextStyle(fontSize: 34, fontWeight: FontWeight.w800, color: tint)),
                      const SizedBox(width: 6),
                      Expanded(
                        child: TextField(
                          controller: _amountCtl,
                          autofocus: true,
                          keyboardType: const TextInputType.numberWithOptions(decimal: true),
                          inputFormatters: [FilteringTextInputFormatter.allow(RegExp(r'[0-9.,]'))],
                          onChanged: (_) => setState(() {}),
                          style: TextStyle(fontSize: 40, fontWeight: FontWeight.w800, color: _ink, letterSpacing: -1),
                          decoration: InputDecoration(
                            isCollapsed: true,
                            border: InputBorder.none,
                            hintText: '0',
                            hintStyle: TextStyle(fontSize: 40, fontWeight: FontWeight.w800, color: _faint),
                          ),
                        ),
                      ),
                      Text('€', style: TextStyle(fontSize: 30, fontWeight: FontWeight.w700, color: _muted)),
                    ]),
                  ),
                  const SizedBox(height: 12),
                  // category
                  _row(
                    onTap: _pickCat,
                    leading: CategoryIcon(icon: _iconOf(_cat.ic), color: _colOf(_cat.col), size: 40, circle: false),
                    label: tr('Kategorija'),
                    value: tr(_cat.cat),
                  ),
                  const SizedBox(height: 10),
                  // date
                  _row(
                    onTap: _pickDate,
                    leading: Container(
                      width: 40,
                      height: 40,
                      decoration: BoxDecoration(color: _soft, borderRadius: BorderRadius.circular(11)),
                      child: Icon(Icons.event_rounded, color: _muted, size: 21),
                    ),
                    label: tr('Data'),
                    value: _dateLabel,
                  ),
                  const SizedBox(height: 10),
                  // note
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
                    decoration: BoxDecoration(color: _card, borderRadius: BorderRadius.circular(16), border: Border.all(color: _hair)),
                    child: Row(children: [
                      Container(
                        width: 40,
                        height: 40,
                        decoration: BoxDecoration(color: _soft, borderRadius: BorderRadius.circular(11)),
                        child: Icon(Icons.notes_rounded, color: _muted, size: 21),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: TextField(
                          controller: _noteCtl,
                          textCapitalization: TextCapitalization.sentences,
                          style: TextStyle(fontSize: 15, fontWeight: FontWeight.w600, color: _ink),
                          decoration: InputDecoration(
                            border: InputBorder.none,
                            hintText: widget.kind == 'transfer' ? tr('Pavadinimas (nebūtina)') : tr('Pastaba (nebūtina)'),
                            hintStyle: TextStyle(fontSize: 15, color: _faint),
                          ),
                        ),
                      ),
                    ]),
                  ),
                  if (widget.kind == 'transfer')
                    Padding(
                      padding: const EdgeInsets.fromLTRB(4, 14, 4, 0),
                      child: Text(tr('Vidiniai pervedimai neįskaičiuojami į išlaidas ar pajamas.'),
                          style: TextStyle(fontSize: 12.5, color: _muted, height: 1.3)),
                    ),
                ],
              ),
            ),
            // save
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
              child: GestureDetector(
                onTap: _valid ? _save : null,
                child: Container(
                  height: 54,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: _valid ? _purple : _faint,
                    borderRadius: BorderRadius.circular(16),
                  ),
                  child: Text(tr('Išsaugoti'), style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w800, color: Colors.white)),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _row({required VoidCallback onTap, required Widget leading, required String label, required String value}) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(16),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
        decoration: BoxDecoration(color: _card, borderRadius: BorderRadius.circular(16), border: Border.all(color: _hair)),
        child: Row(children: [
          leading,
          const SizedBox(width: 12),
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(label, style: TextStyle(fontSize: 12, color: _muted, fontWeight: FontWeight.w600)),
              const SizedBox(height: 2),
              Text(value, style: TextStyle(fontSize: 15.5, fontWeight: FontWeight.w700, color: _ink)),
            ]),
          ),
          Icon(Icons.chevron_right_rounded, color: _faint, size: 22),
        ]),
      ),
    );
  }
}

// ── PAINTERS ──────────────────────────────────────────────────────────────────
class _SparkPainter extends CustomPainter {
  _SparkPainter(this.pts);
  final List<double> pts;
  @override
  void paint(Canvas canvas, Size size) {
    if (pts.length < 2) return;
    final mn = pts.reduce((a, b) => a < b ? a : b);
    final mx = pts.reduce((a, b) => a > b ? a : b);
    final range = (mx - mn).abs() < 1e-6 ? 1.0 : (mx - mn);
    final path = Path();
    for (var i = 0; i < pts.length; i++) {
      final x = i / (pts.length - 1) * size.width;
      final y = size.height - (pts[i] - mn) / range * size.height;
      i == 0 ? path.moveTo(x, y) : path.lineTo(x, y);
    }
    canvas.drawPath(
      path,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..color = _purple,
    );
  }

  @override
  bool shouldRepaint(_SparkPainter old) => false;
}

/// Balance flow chart: a single crisp line (no gradient, no blur haze behind it —
/// the user found those distracting) with a gently pulsing endpoint dot so it
/// still feels "live". Two faint gridlines give the € labels something to sit
/// against. Leaves right padding so the overlaid value labels don't collide with
/// the line's endpoint. [pulse] is a 0→1 animation value from the host widget.
class _NeonSparkPainter extends CustomPainter {
  _NeonSparkPainter(this.pts, {this.dark = true, this.endLabel});
  final List<double> pts;
  final bool dark;
  // Current balance, shown in a coloured pill at the line's endpoint (null hides it).
  final String? endLabel;
  // Room on the right so the endpoint pill + € labels don't touch the line.
  static const double rightPad = 66;

  // One solid line colour (violet on dark, Frost blue on light).
  Color get _line => dark ? const Color(0xFF8B5CF6) : const Color(0xFF2F6BFF);
  Color get _gridColor =>
      (dark ? const Color(0xFFFFFFFF) : const Color(0xFF14203A)).withValues(alpha: 0.07);

  @override
  void paint(Canvas canvas, Size size) {
    final w = (size.width - rightPad).clamp(1.0, size.width);
    // Two faint reference lines (top = max, bottom = min).
    final grid = Paint()
      ..color = _gridColor
      ..strokeWidth = 1;
    canvas.drawLine(const Offset(0, 1), Offset(size.width, 1), grid);
    canvas.drawLine(Offset(0, size.height - 1), Offset(size.width, size.height - 1), grid);
    if (pts.length < 2) return;

    final mn = pts.reduce((a, b) => a < b ? a : b);
    final mx = pts.reduce((a, b) => a > b ? a : b);
    final range = (mx - mn).abs() < 1e-6 ? 1.0 : (mx - mn);
    Offset at(int i) => Offset(
          i / (pts.length - 1) * w,
          (size.height - 8) - (pts[i] - mn) / range * (size.height - 16) + 4,
        );

    final line = Path()..moveTo(at(0).dx, at(0).dy);
    for (var i = 1; i < pts.length; i++) {
      line.lineTo(at(i).dx, at(i).dy);
    }

    // Soft area fill under the line — a clean colour tint (no blur haze).
    final area = Path.from(line)
      ..lineTo(at(pts.length - 1).dx, size.height)
      ..lineTo(0, size.height)
      ..close();
    canvas.drawPath(
      area,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [_line.withValues(alpha: dark ? 0.26 : 0.16), _line.withValues(alpha: 0.0)],
        ).createShader(Rect.fromLTWH(0, 0, size.width, size.height)),
    );

    // Crisp line on top.
    canvas.drawPath(
      line,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.4
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..color = _line,
    );

    // Endpoint dot (white halo for contrast against the fill), then the balance pill.
    final end = at(pts.length - 1);
    canvas.drawCircle(end, 5, Paint()..color = (dark ? const Color(0xFF201545) : const Color(0xFFEEF1F7)));
    canvas.drawCircle(end, 3.4, Paint()..color = _line);

    if (endLabel != null && endLabel!.isNotEmpty) {
      final tp = TextPainter(
        text: TextSpan(text: endLabel, style: const TextStyle(fontSize: 11.5, fontWeight: FontWeight.w800, color: Colors.white)),
        textDirection: TextDirection.ltr,
      )..layout();
      const padH = 8.0, padV = 4.0;
      final pillW = tp.width + padH * 2;
      final pillH = tp.height + padV * 2;
      final px = (end.dx + 8).clamp(0.0, size.width - pillW);
      final py = (end.dy - pillH / 2).clamp(0.0, size.height - pillH);
      final rr = RRect.fromRectAndRadius(Rect.fromLTWH(px, py, pillW, pillH), const Radius.circular(8));
      canvas.drawRRect(rr, Paint()..color = _line);
      tp.paint(canvas, Offset(px + padH, py + padV));
    }
  }

  @override
  bool shouldRepaint(_NeonSparkPainter old) =>
      old.pts != pts || old.dark != dark || old.endLabel != endLabel;
}

/// The weekly chart's background: faint € gridlines (so a bar's height reads as
/// a real amount) plus a dashed "average per day" reference line, so the space
/// behind the bars carries information instead of being empty.
///
/// Geometry matches `_bar`: each bar's Column is bottom-aligned inside the box
/// with a ~26px day-label strip beneath it, so the bars stand on a baseline that
/// far above the box bottom, and grow up to [barMax] px scaled by [maxV].
class _WeekAvgPainter extends CustomPainter {
  _WeekAvgPainter({required this.avg, required this.maxV, required this.barMax, required this.label, this.dark = true});
  final double avg, maxV, barMax;
  final String label;
  final bool dark;

  static const double _bottomInset = 26; // day-label strip + gap under the bars

  Color get _avgColor => dark ? const Color(0xFF6EE7FF) : const Color(0xFF2F6BFF);

  @override
  void paint(Canvas canvas, Size size) {
    if (maxV <= 0) return;
    final baseY = size.height - _bottomInset;
    double yFor(double v) => baseY - (v / maxV * barMax);

    final gridPaint = Paint()
      ..color = (dark ? const Color(0xFFFFFFFF) : const Color(0xFF14203A)).withValues(alpha: dark ? 0.06 : 0.07)
      ..strokeWidth = 1;
    final labelStyle = TextStyle(fontSize: 9, color: dark ? const Color(0xFF6E6790) : const Color(0xFF5C6A85), fontWeight: FontWeight.w600);

    // Faint horizontal gridlines at "nice" euro steps, each labelled on the right.
    final step = _niceStep(maxV / 3);
    for (double v = step; v <= maxV * 1.001; v += step) {
      final y = yFor(v);
      canvas.drawLine(Offset(0, y), Offset(size.width, y), gridPaint);
      final tp = TextPainter(
        text: TextSpan(text: '${v.round()}€', style: labelStyle),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(size.width - tp.width - 1, y - tp.height - 1));
    }
    // Baseline the bars sit on.
    canvas.drawLine(Offset(0, baseY + 0.5), Offset(size.width, baseY + 0.5),
        Paint()..color = (dark ? const Color(0xFFFFFFFF) : const Color(0xFF14203A)).withValues(alpha: dark ? 0.08 : 0.10)..strokeWidth = 1);

    // Dashed average line only (the "vidurkis X €/d." label now lives in the
    // section header, so it can never overlap a bar or its number).
    if (avg > 0) {
      final y = yFor(avg).clamp(8.0, baseY);
      const dash = 5.0, gap = 4.0;
      final avgPaint = Paint()
        ..color = _avgColor.withValues(alpha: dark ? 0.7 : 0.85)
        ..strokeWidth = 1.3;
      for (double x = 0; x < size.width; x += dash + gap) {
        canvas.drawLine(Offset(x, y), Offset((x + dash).clamp(0, size.width), y), avgPaint);
      }
    }
  }

  double _niceStep(double raw) {
    if (raw <= 0) return 1;
    final mag = math.pow(10, (math.log(raw) / math.ln10).floor()).toDouble();
    for (final f in [1, 2, 2.5, 5, 10]) {
      if (f * mag >= raw) return f * mag;
    }
    return 10 * mag;
  }

  @override
  bool shouldRepaint(_WeekAvgPainter old) =>
      old.avg != avg || old.maxV != maxV || old.label != label || old.dark != dark;
}

class _MiniRingPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final c = size.center(Offset.zero);
    final r = size.width / 2 - 3;
    canvas.drawCircle(c, r, Paint()..style = PaintingStyle.stroke..strokeWidth = 5..color = Colors.white.withValues(alpha: 0.25));
    canvas.drawArc(
      Rect.fromCircle(center: c, radius: r),
      -1.5708,
      4.4,
      false,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 5
        ..strokeCap = StrokeCap.round
        ..color = Colors.white,
    );
  }

  @override
  bool shouldRepaint(_MiniRingPainter old) => false;
}

class _Chip extends StatelessWidget {
  const _Chip({required this.icon, required this.label, this.active = false});
