      padding: const EdgeInsets.fromLTRB(20, 0, 20, 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('$_txMonthGen ${tr('biudžetas')}', style: TextStyle(fontSize: 12.5, color: _muted, fontWeight: FontWeight.w600)),
