class _SelectCategorySheetState extends State<_SelectCategorySheet> {
  String _q = '';

  @override
  Widget build(BuildContext context) {
    return DraggableScrollableSheet(
      initialChildSize: 0.88,
      minChildSize: 0.5,
      maxChildSize: 0.95,
      expand: false,
      builder: (_, ctrl) => Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 14, 20, 6),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                GestureDetector(onTap: () => Navigator.pop(context), child: Padding(padding: const EdgeInsets.only(right: 14, top: 4), child: Icon(Icons.close_rounded, size: 24, color: _ink))),
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(tr('SANDORIS'), style: TextStyle(fontSize: 11, color: _muted, fontWeight: FontWeight.w700, letterSpacing: 0.8)),
                    Text(tr('Pasirinkti kategoriją'), style: TextStyle(fontSize: 24, fontWeight: FontWeight.w800, color: _ink, letterSpacing: -0.4)),
                  ],
                ),
              ],
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 8, 20, 8),
            child: TextField(
              onChanged: (v) => setState(() => _q = v.toLowerCase()),
              cursorColor: _purple,
              style: TextStyle(color: _ink),
              decoration: InputDecoration(
                hintText: tr('Ieškoti'),
                hintStyle: TextStyle(color: _faint),
                suffixIcon: Icon(Icons.search_rounded, color: _muted),
                isDense: true,
                contentPadding: const EdgeInsets.symmetric(horizontal: 4, vertical: 12),
                enabledBorder: UnderlineInputBorder(borderSide: BorderSide(color: _hair)),
                focusedBorder: const UnderlineInputBorder(borderSide: BorderSide(color: _purple)),
              ),
            ),
          ),
          Expanded(
            child: ListView(
              controller: ctrl,
              padding: const EdgeInsets.only(bottom: 24),
              children: [
                for (final sec in _taxonomy) ..._section(sec),
              ],
            ),
          ),
        ],
      ),
    );
  }

  List<Widget> _section(Map sec) {
    final subs = (sec['subs'] as List).cast<String>().where((s) => _q.isEmpty || s.toLowerCase().contains(_q)).toList();
    if (subs.isEmpty) return [];
    final color = _secColor[sec['c']] ?? _muted;
    return [
      Padding(
        padding: const EdgeInsets.fromLTRB(20, 14, 20, 6),
        child: Row(children: [
          CategoryIcon(icon: _secIcon[sec['i']] ?? Icons.circle, color: color, size: 30),
          const SizedBox(width: 10),
          Text(tr(sec['sec'] as String), style: TextStyle(fontSize: 15, fontWeight: FontWeight.w800, color: _ink)),
        ]),
      ),
      for (final sub in subs)
        InkWell(
          onTap: () => Navigator.pop(context, {'cat': sub, 'c': sec['c'], 'i': sec['i']}),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(60, 11, 20, 11),
            child: Row(children: [
              Expanded(child: Text(tr(sub), style: TextStyle(fontSize: 15, color: _ink))),
              if (sub == widget.current) const Icon(Icons.check_rounded, size: 20, color: _purple),
            ]),
          ),
        ),
    ];
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// REPORT AN ISSUE sheet
// ══════════════════════════════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════════════════════════════
// MONTH IN REVIEW — full screen (opened from the dashboard review card)
// ══════════════════════════════════════════════════════════════════════════════
class _SecAgg {
  _SecAgg(this.label, this.colorKey);
  final String label;
  final String colorKey;
  double net = 0;
  Color get color => _secColor[colorKey] ?? _muted;
  IconData get icon => _secIcon[_secToIcon[label]] ?? Icons.circle;
}

class _MonthReviewScreen extends StatefulWidget {
  const _MonthReviewScreen({required this.all, required this.balance, required this.budgets, required this.month, required this.monthNom, required this.monthGen, required this.onGoToBudgets});
  final List<Map<String, dynamic>> all;
  final Map<String, dynamic> balance;
  final Map<String, dynamic> budgets;
  final String month, monthNom, monthGen;
  final VoidCallback onGoToBudgets;
  @override
  State<_MonthReviewScreen> createState() => _MonthReviewScreenState();
}

// Session cache for AI month summaries, keyed by month (e.g. "2026-06"), so
// re-opening the same review doesn't pay for another AI call.
final Map<String, String> _monthAiCache = {};

class _MonthReviewScreenState extends State<_MonthReviewScreen> {
  List<Map<String, dynamic>> get _rows => widget.all.where((t) => (t['d'] as String).startsWith(widget.month)).toList();

  // AI-written month narrative: null until it arrives; falls back to a templated
  // summary if the AI is unavailable.
  String? _aiText;
  bool _aiLoading = false;

  @override
  void initState() {
    super.initState();
    _fetchAiSummary();
  }

  Future<void> _fetchAiSummary() async {
    final cached = _monthAiCache[widget.month];
    if (cached != null && cached.isNotEmpty) {
      setState(() => _aiText = cached);
      return;
    }
    setState(() => _aiLoading = true);
    try {
      final text = await BankingService.instance.monthSummary(stats: _buildStats());
      if (!mounted) return;
      if (text.isNotEmpty) _monthAiCache[widget.month] = text;
      setState(() {
        _aiText = text.isNotEmpty ? text : null;
        _aiLoading = false;
      });
    } catch (_) {
      if (mounted) setState(() => _aiLoading = false);
    }
  }

  /// A compact, PII-free block of this month's figures for the AI to narrate —
  /// only aggregates and category labels, never merchant names or single txns.
  String _buildStats() {
    final spent = _sumExpenses(_rows);
    final earned = _sumIncome(_rows);
    final net = earned - spent;
    final secs = _sections();
    final expenseSecs =
        secs.where((s) => !_isIncome(s.label) && !_isTransfer(s.label) && s.net < 0).toList();
    final b = StringBuffer()
      ..writeln('Mėnuo: ${widget.monthNom}')
      ..writeln('Pajamos: ${earned.round()} €')
      ..writeln('Išlaidos: ${spent.round()} €')
      ..writeln('Grynasis rezultatas: ${net.round()} €');
    if (earned > 0) {
      b.writeln('Santaupų norma: ${((earned - spent) / earned * 100).round().clamp(0, 100)} %');
    } else {
      b.writeln('Pajamų šį mėnesį neaptikta.');
    }
    if (expenseSecs.isNotEmpty) {
      b.writeln('Didžiausios išlaidų kategorijos:');
      for (final s in expenseSecs.take(4)) {
        b.writeln('- ${s.label}: ${(-s.net).round()} €');
      }
    }
    final prevRows =
        widget.all.where((t) => (t['d'] as String).startsWith(_prevMonth)).toList();
    if (prevRows.isNotEmpty) {
      b.writeln('Praėjęs mėnuo ($_prevMonthNom): pajamos ${_sumIncome(prevRows).round()} €, '
          'išlaidos ${_sumExpenses(prevRows).round()} €.');
    }
    return b.toString();
  }

  String get _prevMonth {
    final y = int.parse(widget.month.substring(0, 4));
    final m = int.parse(widget.month.substring(5, 7));
    return m == 1 ? '${y - 1}-12' : '$y-${(m - 1).toString().padLeft(2, '0')}';
  }

  String get _prevMonthNom => _monNom[(int.parse(widget.month.substring(5, 7)) + 10) % 12];

  bool _isIncome(String l) => l == 'Pajamos';
  bool _isTransfer(String l) => l == 'Pervedimai'; // 'Kita' = uncategorised spending, counts as expense

  List<_SecAgg> _sections() {
    final m = <String, _SecAgg>{};
    for (final t in _rows) {
      final label = t['sec'] as String;
      final a = m.putIfAbsent(label, () => _SecAgg(label, t['secc'] as String));
      a.net += (t['a'] as num).toDouble();
    }
    final list = m.values.toList()..sort((x, y) => y.net.abs().compareTo(x.net.abs()));
    return list;
  }

  @override
  Widget build(BuildContext context) {
    final secs = _sections();
    final expenseSecs = secs.where((s) => !_isIncome(s.label) && !_isTransfer(s.label) && s.net < 0).toList();
    // Headline figures use the canonical rule (transfers excluded, refunds net
    // spending down) so grynasis == earned − spent and matches the dashboard +
    // review card exactly — never the raw sum-of-amounts that inflated it before.
    final spent = _sumExpenses(_rows);
    final earned = _sumIncome(_rows);
    // "Gauta" = all money that landed from outside (income + incoming transfers).
    // Display-only — net/savings below still use `earned` (canonical income).
    final received = _sumReceived(_rows);
    final net = earned - spent;
    final savings = earned > 0 ? ((earned - spent) / earned * 100).round().clamp(0, 100) : 0;
    // Real saving streak (was hardcoded "2 mėn."), derived from all months.
    final mkeys = (widget.all.map((t) => (t['d'] as String).substring(0, 7)).toSet().toList()..sort());
    int savOf(List<Map<String, dynamic>> r) {
      final e = _sumIncome(r);
      return e > 0 ? ((e - _sumExpenses(r)) / e * 100).round().clamp(0, 100) : 0;
    }
    final streak = _streakOf(mkeys, (mk) => widget.all.where((t) => (t['d'] as String).startsWith(mk)).toList(), savOf);

    return Scaffold(
      backgroundColor: _bg,
      body: Column(
        children: [
          _header(),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.only(bottom: 30),
              children: [
