          Text('−${_eur(v)}', style: TextStyle(fontSize: 15, fontWeight: FontWeight.w800, color: _ink)),
          Text(label, style: TextStyle(fontSize: 12, color: _muted)),
        ]),
      ]),
    );
  }

  // ── AVERAGE DAILY SPENDING ──
  int get _elapsedDays {
    final now = DateTime.now();
    final curCal = '${now.year}-${now.month.toString().padLeft(2, '0')}';
    // Current calendar month → days elapsed so far (today's day); any earlier
    // month is complete → full month. (Was latest-tx-day + 1, off by one.)
    if (widget.month == curCal) return now.day.clamp(1, _daysInMonth);
    return _daysInMonth;
  }

  Widget _avgDaily(List<_SecAgg> expenseSecs) {
    final days = _elapsedDays;
    final totalAvg = expenseSecs.fold(0.0, (s, x) => s - x.net) / days;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _sectionLabel('Vidutinės dienos išlaidos'),
        Container(
          margin: const EdgeInsets.fromLTRB(16, 0, 16, 14),
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(color: _card, borderRadius: BorderRadius.circular(16), border: Border.all(color: _hair)),
          child: Column(children: [
            Row(children: [
              Text(widget.monthNom, style: TextStyle(fontSize: 17, fontWeight: FontWeight.w800, color: _ink)),
              const Spacer(),
              Text('−${totalAvg.toStringAsFixed(2).replaceAll('.', ',')} €', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w800, color: _ink)),
            ]),
            const SizedBox(height: 12),
            for (final s in expenseSecs)
              Padding(
                padding: const EdgeInsets.only(bottom: 9),
                child: Row(children: [
                  CategoryIcon(icon: s.icon, color: s.color, size: 26),
                  const SizedBox(width: 10),
                  Expanded(child: Text(tr(s.label), style: TextStyle(fontSize: 14.5, color: _ink))),
                  Text('−${((-s.net) / days).toStringAsFixed(2).replaceAll('.', ',')} €',
                      style: TextStyle(fontSize: 14.5, fontWeight: FontWeight.w700, color: _ink, fontFeatures: const [FontFeature.tabularFigures()])),
                ]),
              ),
          ]),
        ),
      ],
    );
  }

  // ── MERCHANTS ──
  Widget _merchants() {
    final count = _rows
        .where((t) => !_isIncome(t['sec'] as String) && !_isTransfer(t['sec'] as String) && (t['a'] as num) < 0)
        .map((t) => t['mkey'])
        .toSet()
        .length;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _sectionLabel('Prekybininkai'),
        Container(
          margin: const EdgeInsets.fromLTRB(16, 0, 16, 4),
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 18),
          decoration: BoxDecoration(color: _card, borderRadius: BorderRadius.circular(16), border: Border.all(color: _hair)),
          child: Row(children: [
            Text('$count ${tr('prekybininkai')}', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w700, color: _ink)),
            const Spacer(),
            const Icon(Icons.keyboard_arrow_down_rounded, color: _purple),
          ]),
        ),
      ],
    );
  }

  // ── LARGEST EXPENSES ──
  Widget _largest() {
    final exp = _rows.where((t) => (t['a'] as num) < 0).toList()..sort((a, b) => (a['a'] as num).compareTo(b['a'] as num));
    final top = exp.take(5).toList();
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _sectionLabel('Didžiausios išlaidos'),
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 0, 16, 0),
          child: AppCard(color: _card, border: _hair, 
            child: Column(children: [
              for (var i = 0; i < top.length; i++) ...[
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
                  child: Row(children: [
                    CategoryIcon(icon: _iconOf(top[i]['ic'] as String?), color: _colOf(top[i]['col'] as String?), size: 40, circle: false, merchant: _logoOf(top[i])),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Text(_shortNm(top[i]['nm'] as String), style: TextStyle(fontSize: 15.5, fontWeight: FontWeight.w700, color: _ink)),
                        const SizedBox(height: 2),
                        Text('${top[i]['md']}; ${tr((top[i]['cat'] ?? '').toString())}', maxLines: 1, overflow: TextOverflow.ellipsis, style: TextStyle(fontSize: 12.5, color: _muted)),
                      ]),
                    ),
                    const SizedBox(width: 8),
                    Text(_eur((top[i]['a'] as num).toDouble(), signed: true),
                        style: TextStyle(fontSize: 15.5, fontWeight: FontWeight.w700, color: _ink, fontFeatures: const [FontFeature.tabularFigures()])),
                  ]),
                ),
                if (i != top.length - 1) const RowDivider(indent: 66),
              ],
            ]),
          ),
        ),
      ],
    );
  }
}

class _RingProgressPainter extends CustomPainter {
  _RingProgressPainter(this.ratio, [this.arcColor = _good]);
  final double ratio;
  final Color arcColor;
  @override
  void paint(Canvas canvas, Size size) {
    final c = size.center(Offset.zero);
    final r = size.width / 2 - 4;
    canvas.drawCircle(c, r, Paint()..style = PaintingStyle.stroke..strokeWidth = 6..color = const Color(0xFFE7F0E8));
    canvas.drawArc(Rect.fromCircle(center: c, radius: r), -math.pi / 2, 2 * math.pi * ratio.clamp(0.0, 1.0), false,
        Paint()..style = PaintingStyle.stroke..strokeWidth = 6..strokeCap = StrokeCap.round..color = arcColor);
  }

  @override
  bool shouldRepaint(_RingProgressPainter old) => old.ratio != ratio;
}

class _DonutPainter extends CustomPainter {
  _DonutPainter(this.segments);
  final List<List<dynamic>> segments; // [value(double), color(Color)]
  static const double stroke = 15;
  @override
  void paint(Canvas canvas, Size size) {
    final rect = Rect.fromCircle(center: size.center(Offset.zero), radius: (math.min(size.width, size.height) - stroke) / 2);
    final total = segments.fold(0.0, (t, s) => t + (s[0] as double).abs());
    canvas.drawArc(rect, 0, 2 * math.pi, false, Paint()..style = PaintingStyle.stroke..strokeWidth = stroke..color = DS.track);
    if (total <= 0) return;
    if (segments.length == 1) {
      canvas.drawArc(rect, -math.pi / 2, 2 * math.pi, false,
          Paint()..style = PaintingStyle.stroke..strokeWidth = stroke..color = segments[0][1] as Color..strokeCap = StrokeCap.round);
      return;
    }
    var start = -math.pi / 2;
    const gap = 0.06;
    for (final s in segments) {
      final frac = (s[0] as double).abs() / total;
      final sweep = 2 * math.pi * frac - gap;
      if (sweep > 0) {
        canvas.drawArc(rect, start + gap / 2, sweep, false,
            Paint()..style = PaintingStyle.stroke..strokeWidth = stroke..color = s[1] as Color..strokeCap = StrokeCap.round);
      }
      start += 2 * math.pi * frac;
    }
  }

  @override
  bool shouldRepaint(_DonutPainter old) => true;
}

