// ACCOUNT TAB — net worth, assets, accounts (real balance data) + Settings
// ══════════════════════════════════════════════════════════════════════════════
class _AccountTab extends StatefulWidget {
  const _AccountTab({required this.balance});
  final Map<String, dynamic> balance;
  @override
  State<_AccountTab> createState() => _AccountTabState();
}

class _AccountTabState extends State<_AccountTab> {
  bool _promo = true;
  late List<Map<String, dynamic>> _assets = DashboardStore.manualAssets();

  // Bank balance = the live truth from Enable Banking (never touched by cash).
  double get _bankBalance => ((widget.balance['current'] ?? 0) as num).toDouble();
  // Manually-added cash / savings the bank can't see.
  double get _assetsSum =>
      _assets.fold(0.0, (s, a) => s + ((a['amount'] as num?)?.toDouble() ?? 0));
  // Net worth = bank + cash. Spending analytics still use the bank balance only.
  double get _netWorth => _bankBalance + _assetsSum;
  List<Map<String, dynamic>> get _accounts => ((widget.balance['accounts'] as List?) ?? const []).cast<Map<String, dynamic>>();

  void _soon() => _snack(tr('Netrukus'));

  void _snack(String m) => ScaffoldMessenger.of(context)
    ..hideCurrentSnackBar()
    ..showSnackBar(SnackBar(content: Text(m), duration: const Duration(milliseconds: 1600)));

  @override
  Widget build(BuildContext context) {
    final spark = (widget.balance['series'] as List)
        .cast<Map<String, dynamic>>()
        .map((p) => (p['v'] as num).toDouble())
        .toList();
    // sub-sample the 245-pt series for a light sparkline
    final step = (spark.length / 60).ceil().clamp(1, 999);
    final thin = [for (var i = 0; i < spark.length; i += step) spark[i]];

    return SafeArea(
      bottom: false,
      child: ListView(
        padding: const EdgeInsets.only(bottom: 28),
        children: [
          _header(),
          _settingsRow(),
          if (_promo) _promoCard(),
          _netWorthCard(),
          _assetsCard(),
          _totalBalanceCard(thin),
          _accountsCard(),
          _feedbackCard(),
        ],
      ),
    );
  }

  Widget _header() => Padding(
        padding: const EdgeInsets.fromLTRB(16, 6, 16, 12),
        child: Row(children: [
          Text(tr('Paskyra'), style: TextStyle(fontSize: 30, fontWeight: FontWeight.w800, color: _ink, letterSpacing: -0.5)),
        ]),
      );

  Widget _settingsRow() => Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
        child: GestureDetector(
          onTap: () => Navigator.of(context).push(MaterialPageRoute(builder: (_) => const _SettingsScreen())),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
            decoration: BoxDecoration(color: _card, borderRadius: BorderRadius.circular(16), boxShadow: DS.e1),
            child: Row(children: [
              Container(
                width: 40, height: 40,
                decoration: BoxDecoration(color: _purple, borderRadius: BorderRadius.circular(12)),
                child: const Icon(Icons.settings_rounded, size: 22, color: Colors.white),
              ),
              const SizedBox(width: 13),
              Text('Nustatymai', style: TextStyle(fontSize: 16.5, fontWeight: FontWeight.w700, color: _ink)),
              const Spacer(),
              Container(
                width: 40, height: 40,
                decoration: BoxDecoration(color: _purpleSoft, shape: BoxShape.circle),
                child: const Icon(Icons.person_rounded, size: 22, color: _purple),
              ),
            ]),
          ),
        ),
