  // ── preference sheets ────────────────────────────────────────────────────────
  void _pickCurrency() {
    // Curated set matching Vaultie's EU rollout (EUR base, NOK for salary, USD)
    const opts = [
      ['Euras (EUR)', '€', 'Bazinė valiuta'],
      ['Norvegijos krona (NOK)', 'kr', '1 EUR = 11,14 NOK'],
      ['JAV doleris (USD)', '\$', '1 EUR = 1,14 USD'],
    ];
    _sheet(tr('Numatytoji valiuta'), [
      for (final o in opts)
        _radioRow(tr(o[0]), tr(o[2]), o[1], _currency == o[0], () {
          AppPrefs.setCurrency(o[1]);
          setState(() => _currency = o[0]);
          Navigator.pop(context);
        }),
    ]);
  }

  void _pickLanguage() {
    // Manual choice wins over the device Region default; the app rebuilds via
    // the AppPrefs.locale notifier.
    final opts = <List<dynamic>>[
      ['Sistemos numatytoji', null],
      ['Lietuvių', const Locale('lt')],
      ['English', const Locale('en')],
    ];
    _sheet(tr('Kalba'), [
      for (final o in opts)
        _radioRow(tr(o[0] as String), '', '', _langLabel == o[0], () {
          AppPrefs.setLocale(o[1] as Locale?);
          setState(() {});
          Navigator.pop(context);
        }),
    ]);
  }

  void _pickTheme() {
    const opts = [
      ['Sistemos numatytoji', Icons.brightness_auto_rounded],
      ['Šviesi', Icons.light_mode_rounded],
      ['Tamsi', Icons.dark_mode_rounded],
    ];
    _sheet(tr('Tema'), [
      for (final o in opts)
        InkWell(
          onTap: () {
            final label = o[0] as String;
            final dark = label == 'Tamsi' ||
                (label == 'Sistemos numatytoji' &&
                    MediaQuery.of(context).platformBrightness == Brightness.dark);
            // Persist the choice (Hive) AND update the app-wide notifier so the
            // base theme rebuilds — otherwise the pick only changed the dashboard
            // tokens in memory and reverted to the saved value on next launch.
            AppPrefs.setDarkMode(dark);
            _applyTheme(dark);
            setState(() => _theme = label);
            Navigator.pop(context);
          },
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 16),
            child: Row(children: [
              Icon(o[1] as IconData, size: 23, color: _purple),
              const SizedBox(width: 16),
              Text(tr(o[0] as String), style: TextStyle(fontSize: 16.5, fontWeight: FontWeight.w600, color: _ink)),
              const Spacer(),
              if (_theme == o[0]) const Icon(Icons.check_rounded, size: 22, color: _purple),
            ]),
          ),
        ),
    ]);
  }

  // ── PIN / Face ID ────────────────────────────────────────────────────────
  Future<void> _togglePin(bool on) async {
    if (on) {
      // Set a new PIN: enter + confirm on the dedicated pad.
      final pin = await Navigator.of(context).push<String>(
        MaterialPageRoute(fullscreenDialog: true, builder: (_) => const PinSetupScreen()),
      );
      if (pin == null || pin.isEmpty) return; // cancelled
      await AppLock.setPin(pin);
      if (mounted) setState(() => _pin = true);
    } else {
      // Removing the PIN also disables Face ID. The user already passed the lock
      // to reach Settings, so a plain confirm is enough here.
      final ok = await showDialog<bool>(
        context: context,
        builder: (ctx) => AlertDialog(
          backgroundColor: _card,
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
          title: Text(tr('Išjungti PIN?'), style: TextStyle(fontWeight: FontWeight.w800, color: _ink)),
          content: Text(tr('Vaultie nebebus užrakinta. Galėsi bet kada vėl įjungti PIN.'),
              style: TextStyle(color: _muted, height: 1.45)),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx, false), child: Text(tr('Atšaukti'), style: TextStyle(color: _muted))),
            TextButton(onPressed: () => Navigator.pop(ctx, true),
                child: Text(tr('Išjungti'), style: const TextStyle(color: _purple, fontWeight: FontWeight.w800))),
          ],
        ),
      );
      if (ok != true) return;
      await AppLock.clearPin();
      if (mounted) setState(() { _pin = false; _faceId = false; });
    }
  }

  Future<void> _toggleFaceId(bool on) async {
    await AppLock.setFaceId(on);
