  // ── P0 account actions ──────────────────────────────────────────────────────
  // The real app path runs these against Firebase; the design preview harness
  // has no Firebase, so the auth/session calls are guarded and fall back to an
  // honest note instead of crashing.
  void _snack(String m) => ScaffoldMessenger.of(context)
    ..clearSnackBars()
    ..showSnackBar(SnackBar(content: Text(m), duration: const Duration(seconds: 2)));

  void _soon() => _snack(tr('Netrukus'));

  Future<void> _signOut() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: _card,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
        title: Text(tr('Atsijungti?'), style: TextStyle(fontWeight: FontWeight.w800, color: _ink)),
        content: Text(tr('Grįši į prisijungimo ekraną. Tavo duomenys liks išsaugoti šiame telefone ir bus vėl matomi prisijungus.'),
            style: TextStyle(color: _muted, height: 1.45)),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: Text(tr('Atšaukti'), style: TextStyle(color: _muted))),
          TextButton(onPressed: () => Navigator.pop(ctx, true),
              child: Text(tr('Atsijungti'), style: const TextStyle(color: _purple, fontWeight: FontWeight.w800))),
        ],
      ),
    );
    if (ok != true) return;
    try {
      await AuthService().signOut();
      await onSignedOut();
    } catch (_) {
      if (mounted) _snack(tr('Atsijungti galima tik tikroje programoje.'));
      return;
    }
    if (!mounted) return;
    Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
      MaterialPageRoute(builder: (_) => const LoginScreen()), (r) => false);
  }

  Future<void> _confirmDelete() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: _card,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
        title: Text(tr('Ištrinti paskyrą?'), style: TextStyle(fontWeight: FontWeight.w800, color: _ink)),
        content: Text(
          tr('Tai VISAM LAIKUI ištrins tavo Vaultie paskyrą ir visus duomenis šiame telefone — sandorius, prenumeratas, biudžetus. Banko ryšys bus atjungtas. Šio veiksmo anuliuoti negalima.'),
          style: TextStyle(color: _muted, height: 1.45),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: Text(tr('Atšaukti'), style: TextStyle(color: _muted))),
          TextButton(onPressed: () => Navigator.pop(ctx, true),
              child: Text(tr('Ištrinti'), style: const TextStyle(color: Color(0xFFE0574F), fontWeight: FontWeight.w800))),
        ],
      ),
    );
    if (ok == true) await _deleteAccount();
  }

  Future<void> _deleteAccount() async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      final auth = AuthService();
      try {
        await auth.deleteAccount();
      } on FirebaseAuthException catch (e) {
        // Firebase requires a fresh login before deletion — re-auth then retry.
        if (e.code != 'requires-recent-login') rethrow;
        if (!await _reauth(auth)) return;
        await auth.deleteAccount();
      }
      try {
        await wipeLocalDataAndForget();
      } catch (_) {/* preview: no Hive/session */}
      if (!mounted) return;
      Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
        MaterialPageRoute(builder: (_) => const LoginScreen()), (r) => false);
    } on FirebaseAuthException catch (e) {
      // Cancelling the Apple re-auth sheet is not a failure — just stop.
      if (e.code == 'apple-reauth-cancelled') return;
      if (mounted) _snack(authErrorMessage(e, isLithuanian: !_enUi));
    } catch (e) {
      // Some firebase_auth versions throw a non-Firebase (Pigeon) error even
      // though the native delete succeeded. If the user is gone, it worked.
      if (AuthService().currentUser == null) {
        try {
          await wipeLocalDataAndForget();
        } catch (_) {}
        if (!mounted) return;
        Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
          MaterialPageRoute(builder: (_) => const LoginScreen()), (r) => false);
        return;
      }
      if (mounted) _snack(_enUi ? 'Could not delete your account.' : 'Nepavyko ištrinti paskyros.');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<bool> _reauth(AuthService auth) async {
    try {
      if (auth.isGoogleUser) return await auth.reauthenticateWithGoogle();
      if (auth.isAppleUser) return await auth.reauthenticateWithApple();
    } catch (_) {
      return false;
    }
    // Email/password account — ask for the password to confirm identity.
    final pw = await showDialog<String>(context: context, builder: (ctx) => _PasswordPrompt());
    if (pw == null || pw.isEmpty) return false;
    try {
      await auth.reauthenticateWithPassword(pw);
      return true;
    } catch (_) {
      if (mounted) _snack(tr('Neteisingas slaptažodis.'));
      return false;
    }
  }
}

// Confirms identity with the account password before an irreversible delete.
class _PasswordPrompt extends StatefulWidget {
  @override
  State<_PasswordPrompt> createState() => _PasswordPromptState();
}

class _PasswordPromptState extends State<_PasswordPrompt> {
  final _ctl = TextEditingController();

  @override
  void dispose() {
    _ctl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      backgroundColor: _card,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      title: Text(tr('Patvirtink slaptažodį'), style: TextStyle(fontWeight: FontWeight.w800, color: _ink)),
      content: TextField(
        controller: _ctl,
        autofocus: true,
        obscureText: true,
        cursorColor: _purple,
        style: TextStyle(color: _ink, fontSize: 17),
        decoration: InputDecoration(
          hintText: tr('Slaptažodis'),
          hintStyle: TextStyle(color: _faint),
          enabledBorder: UnderlineInputBorder(borderSide: BorderSide(color: _hair)),
          focusedBorder: const UnderlineInputBorder(borderSide: BorderSide(color: _purple, width: 2)),
        ),
        onSubmitted: (v) => Navigator.pop(context, v),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(context), child: Text(tr('Atšaukti'), style: TextStyle(color: _muted))),
        TextButton(onPressed: () => Navigator.pop(context, _ctl.text),
            child: Text(tr('Patvirtinti'), style: const TextStyle(color: _purple, fontWeight: FontWeight.w800))),
      ],
    );
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// SEARCH — filter transactions by merchant / category
// ══════════════════════════════════════════════════════════════════════════════
class _SearchScreen extends StatefulWidget {
  const _SearchScreen({required this.all, required this.budgets});
  final List<Map<String, dynamic>> all;
  final Map<String, dynamic> budgets;
  @override
  State<_SearchScreen> createState() => _SearchScreenState();
}

class _SearchScreenState extends State<_SearchScreen> {
  String _q = '';

  List<Map<String, dynamic>> get _results {
    final q = _fold(_q.trim());
    if (q.isEmpty) return const [];
    final r = widget.all.where((t) {
      // Match merchant (raw + shortened), category AND section, all diacritic-folded.
      final hay = _fold('${t['nm']} ${_shortNm(t['nm'] as String)} ${t['cat']} ${t['sec'] ?? ''}');
      return hay.contains(q);
    }).toList();
    r.sort((a, b) => (b['d'] as String).compareTo(a['d'] as String));
    return r;
  }

  void _open(Map<String, dynamic> t) {
    final day = {
      'date': t['d'], 'label': t['md'], 'wd': t['wd'] ?? '',
      'day': int.tryParse((t['d'] as String).substring(8, 10)) ?? 1,
      'total': t['a'], 'tx': [t],
    };
    Navigator.of(context).push(MaterialPageRoute(
      builder: (_) => _TxDetailScreen(tx: t, day: day, all: widget.all, budgets: widget.budgets, single: true),
    ));
  }

  @override
  Widget build(BuildContext context) {
    final res = _results;
    final total = res.fold(0.0, (s, t) => s + (t['a'] as num).toDouble());
    return Scaffold(
      backgroundColor: _bg,
      appBar: AppBar(
        backgroundColor: _card,
        elevation: 0,
        scrolledUnderElevation: 0,
        titleSpacing: 0,
        leading: IconButton(icon: Icon(Icons.chevron_left_rounded, size: 30, color: _ink), onPressed: () => Navigator.pop(context)),
        title: TextField(
          autofocus: true,
          onChanged: (v) => setState(() => _q = v),
          style: TextStyle(fontSize: 17, color: _ink),
          decoration: InputDecoration(
            hintText: tr('Ieškok prekybininko ar kategorijos…'),
            hintStyle: TextStyle(color: _faint, fontSize: 16),
            border: InputBorder.none,
          ),
        ),
      ),
      body: _q.trim().isEmpty
          ? Center(
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 40),
                child: Text(tr('Įrašyk, ko ieškai — pvz. „Maxima", „kuras", „Netflix".'),
                    textAlign: TextAlign.center, style: TextStyle(fontSize: 15, color: _muted, height: 1.4)),
              ),
            )
          : res.isEmpty
              ? Center(child: Text(tr('Nieko nerasta'), style: TextStyle(fontSize: 16, color: _muted)))
              : ListView(
                  padding: const EdgeInsets.only(bottom: 24),
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(20, 12, 20, 8),
                      child: Row(children: [
                        Text('${res.length} ${res.length == 1 ? tr('sandoris') : tr('sandoriai')}',
                            style: TextStyle(fontSize: 13.5, color: _muted)),
                        const Spacer(),
                        Text(_eur(total, signed: true),
                            style: TextStyle(fontSize: 13.5, fontWeight: FontWeight.w700, color: total >= 0 ? _good : _ink)),
                      ]),
                    ),
                    for (final t in res)
                      InkWell(
                        onTap: () => _open(t),
                        child: Container(
                          margin: const EdgeInsets.fromLTRB(16, 0, 16, 8),
                          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
                          decoration: BoxDecoration(color: _card, borderRadius: BorderRadius.circular(14), border: Border.all(color: _hair)),
                          child: Row(children: [
                            CategoryIcon(icon: _iconOf(t['ic'] as String?), color: _colOf(t['col'] as String?), size: 40, merchant: _logoOf(t)),
                            const SizedBox(width: 12),
                            Expanded(
                              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                                Text(_shortNm(t['nm'] as String), maxLines: 1, overflow: TextOverflow.ellipsis,
                                    style: TextStyle(fontSize: 15.5, fontWeight: FontWeight.w600, color: _ink)),
                                Text('${tr((t['cat'] ?? '').toString())} · ${t['md']}', style: TextStyle(fontSize: 12.5, color: _muted)),
                              ]),
                            ),
                            Text(_eur((t['a'] as num).toDouble(), signed: true),
                                style: TextStyle(fontSize: 15.5, fontWeight: FontWeight.w700,
                                    color: (t['a'] as num) >= 0 ? _good : _ink, fontFeatures: const [FontFeature.tabularFigures()])),
                          ]),
                        ),
                      ),
                  ],
                ),
    );
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// AI FINANCE CHAT — the "AI pokalbis" tab
// ══════════════════════════════════════════════════════════════════════════════

/// Builds a compact, PRIVACY-SAFE summary of the user's finances to send to the
/// AI. Only aggregates leave the phone: category totals, subscription names +
/// amounts, and per-bank balances. NEVER raw transactions, IBANs, or the names
/// of people the user paid — transfers are summed as one anonymous line, never
/// itemised. This is the whole payload the assistant ever sees.
String buildFinanceSummary(Map<String, dynamic> d) {
  final b = StringBuffer();
  num n(v) => (v is num) ? v : 0;

  // ── Balances (per bank, no IBANs) ──
  final bal = (d['balance'] as Map?) ?? const {};
  final accts = ((bal['accounts'] as List?) ?? const []).whereType<Map>().toList();
  b.writeln('BALANSAS: ${_eur(n(bal['current']))} iš viso.');
  for (final a in accts) {
    final bank = (a['bank'] ?? a['name'] ?? 'Sąskaita').toString();
    b.writeln('  - $bank: ${_eur(n(a['amount']))}');
  }

  // ── This month's spending by category (canonical: outflow, non-transfer) ──
  final all = ((d['all'] as List?) ?? const []).whereType<Map>().toList();
  String monthOf(Map t) => (t['d'] as String? ?? '').padRight(7).substring(0, 7);
  final months = all.map(monthOf).where((m) => m.trim().isNotEmpty).toList()..sort();
  final month = months.isNotEmpty ? months.last : '';
  final byCat = <String, double>{};
  double income = 0, spent = 0;
  for (final t in all) {
    if (monthOf(t) != month) continue;
    final sec = (t['sec'] as String? ?? '');
    final isTransfer = sec == 'Pervedimai' || t['col'] == 'transfer';
    if (isTransfer) continue;
    final a = n(t['a']).toDouble();
    if (a < 0) {
      spent += -a;
      final cat = (t['cat'] as String? ?? 'Kita');
      byCat[cat] = (byCat[cat] ?? 0) + -a;
      // NOTE: we deliberately do NOT track per-category payee names here. An
      // individual's name (e.g. a rent/loan paid to a person, which the engine
      // classifies as Būstas/Finansai, not Pervedimai) could otherwise slip into
      // the AI summary. Only category TOTALS leave the device.
    } else if (a > 0 && t['pos'] == true) {
      income += a;
    }
  }
  if (month.isNotEmpty) {
    b.writeln('\nŠIS MĖNUO ($month):');
    b.writeln('  Išlaidos: ${_eur(spent)}');
    if (income > 0) b.writeln('  Pajamos: ${_eur(income)}');
    final cats = byCat.entries.toList()..sort((x, y) => y.value.compareTo(x.value));
    if (cats.isNotEmpty) {
      b.writeln('  Išlaidos pagal kategoriją:');
      for (final e in cats.take(12)) {
        b.writeln('    - ${e.key}: ${_eur(e.value)}');
      }
    }
  }

  // ── Recurring commitments (active, non-transfer; names are merchants) ──
  final subs = (d['subs'] as Map?) ?? const {};
  final items = ((subs['items'] as List?) ?? const []).whereType<Map>()
      .where((it) => it['active'] == true && it['type'] != 'transfer')
      .toList()
    ..sort((x, y) => n(y['monthly']).compareTo(n(x['monthly'])));
  if (items.isNotEmpty) {
    final total = items.fold<double>(0, (s, it) => s + n(it['monthly']).toDouble());
    b.writeln('\nPRENUMERATOS IR SĄSKAITOS (${_eur(total)} per mėn.):');
    for (final it in items.take(20)) {
      final name = (it['name'] ?? '—').toString();
      final cycle = (it['cycle'] ?? 'monthly').toString();
      b.writeln('  - $name: ${_eur(n(it['monthly']))}/mėn (ciklas: $cycle)');
    }
  }

  return b.toString().trim();
}

class _AiChatTab extends StatefulWidget {
  const _AiChatTab({required this.data});
  final Map<String, dynamic> data;
  @override
  State<_AiChatTab> createState() => _AiChatTabState();
}

class _ChatMsg {
  _ChatMsg(this.role, this.text);
  final String role; // 'user' | 'assistant'
  final String text;
}

class _AiChatTabState extends State<_AiChatTab> {
  final _input = TextEditingController();
  final _scroll = ScrollController();
  final _msgs = <_ChatMsg>[];
  bool _sending = false;

  // A few tappable starters so the empty state isn't a blank box.
  static const _starters = [
    'Kiek išleidau šį mėnesį?',
    'Kokia mano brangiausia prenumerata?',
    'Kur galėčiau sutaupyti?',
    'Į ką daugiausiai išleidžiu?',
  ];

  @override
  void dispose() {
    _input.dispose();
    _scroll.dispose();
    super.dispose();
  }

  Future<void> _ensureConsent() async {
    if (AppPrefs.aiChatConsent) return;
    final ok = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (ctx) => AlertDialog(
        backgroundColor: _card,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(22)),
        title: Text(tr('AI pokalbis apie tavo finansus'),
            style: TextStyle(fontWeight: FontWeight.w800, color: _ink, fontSize: 19)),
        content: Text(
          tr('Kad atsakytų į klausimus, appsas siunčia mūsų AI tiekėjui (Anthropic) '
          'TAVO finansų SANTRAUKĄ — banko likučius, išlaidas pagal kategoriją ir '
          'tavo pasikartojančių mokėjimų pavadinimus (pvz. „Netflix").\n\n'
          '• Nesiunčiami atskiri sandoriai, IBAN‑ai ar kortelių numeriai.\n'
          '• Duomenys NENAUDOJAMI dirbtinio intelekto treniravimui.\n'
          '• Tai nėra finansinė konsultacija.'),
          style: TextStyle(color: _muted, height: 1.5, fontSize: 14.5),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text(tr('Atšaukti'), style: TextStyle(color: _muted)),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: Text(tr('Sutinku ir tęsiu'),
                style: const TextStyle(color: _purple, fontWeight: FontWeight.w800)),
          ),
        ],
      ),
    );
    if (ok == true) await AppPrefs.setAiChatConsent(true);
  }

  Future<void> _send(String raw) async {
    final text = raw.trim();
    if (text.isEmpty || _sending) return;
    await _ensureConsent();
    if (!AppPrefs.aiChatConsent || !mounted) return;

    setState(() {
      _msgs.add(_ChatMsg('user', text));
      _sending = true;
      _input.clear();
    });
    _scrollToEnd();

    try {
      final history = _msgs.map((m) => {'role': m.role, 'text': m.text}).toList();
      final reply = await BankingService.instance.financeChat(
        summary: buildFinanceSummary(widget.data),
        messages: history,
      );
      if (!mounted) return;
      setState(() => _msgs.add(_ChatMsg('assistant',
          reply.isEmpty ? tr('Atsiprašau, nepavyko atsakyti. Pabandyk dar kartą.') : reply)));
    } catch (_) {
      if (!mounted) return;
      setState(() => _msgs.add(_ChatMsg('assistant',
          tr('Nepavyko susisiekti su serveriu. Patikrink ryšį ir bandyk dar kartą.'))));
    } finally {
      if (mounted) setState(() => _sending = false);
      _scrollToEnd();
    }
  }

  void _scrollToEnd() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_scroll.hasClients) {
        _scroll.animateTo(_scroll.position.maxScrollExtent,
            duration: const Duration(milliseconds: 250), curve: Curves.easeOut);
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final hasBank = DashboardStore.bankCount > 0 || (widget.data?['all'] as List?)?.isNotEmpty == true;
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(20, 8, 20, 4),
          child: Row(children: [
            Container(
              width: 40, height: 40, alignment: Alignment.center,
              decoration: BoxDecoration(color: _purpleSoft, borderRadius: BorderRadius.circular(13)),
              child: const Icon(Icons.auto_awesome_rounded, color: _purple, size: 22),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(tr('AI pokalbis'), style: TextStyle(fontSize: 20, fontWeight: FontWeight.w800, color: _ink)),
                Text(tr('Klausk apie savo pinigus'), style: TextStyle(fontSize: 13, color: _muted)),
              ]),
            ),
          ]),
        ),
        Expanded(
          child: _msgs.isEmpty
              ? _emptyState(hasBank)
              : ListView.builder(
                  controller: _scroll,
                  padding: const EdgeInsets.fromLTRB(16, 8, 16, 12),
                  itemCount: _msgs.length + (_sending ? 1 : 0),
                  itemBuilder: (_, i) {
                    if (i >= _msgs.length) return _typing();
                    return _bubble(_msgs[i]);
                  },
                ),
        ),
        _composer(hasBank),
      ],
    );
  }

  Widget _emptyState(bool hasBank) {
    if (!hasBank) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Text(tr('Prijunk banką, kad galėčiau atsakyti apie tavo finansus.'),
              textAlign: TextAlign.center, style: TextStyle(color: _muted, height: 1.5, fontSize: 15)),
        ),
      );
    }
    return ListView(
      padding: const EdgeInsets.fromLTRB(20, 20, 20, 12),
      children: [
        Text(tr('Pabandyk paklausti:'),
            style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: _muted)),
        const SizedBox(height: 12),
        for (final s in _starters)
          Padding(
            padding: const EdgeInsets.only(bottom: 10),
            child: GestureDetector(
              onTap: () => _send(s),
              child: Container(
                width: double.infinity,
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
                decoration: BoxDecoration(
                  color: _card,
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(color: _hair),
                ),
                child: Row(children: [
                  const Icon(Icons.chat_bubble_outline_rounded, size: 17, color: _purple),
                  const SizedBox(width: 12),
                  Expanded(child: Text(tr(s), style: TextStyle(fontSize: 15, color: _ink))),
                ]),
              ),
            ),
          ),
      ],
    );
  }

  Widget _bubble(_ChatMsg m) {
    final isUser = m.role == 'user';
    return Align(
      alignment: isUser ? Alignment.centerRight : Alignment.centerLeft,
      child: Container(
        constraints: BoxConstraints(maxWidth: MediaQuery.of(context).size.width * 0.82),
        margin: const EdgeInsets.symmetric(vertical: 5),
        padding: const EdgeInsets.symmetric(horizontal: 15, vertical: 11),
        decoration: BoxDecoration(
          color: isUser ? _purple : _card,
          borderRadius: BorderRadius.only(
            topLeft: const Radius.circular(18),
            topRight: const Radius.circular(18),
            bottomLeft: Radius.circular(isUser ? 18 : 5),
            bottomRight: Radius.circular(isUser ? 5 : 18),
          ),
          border: isUser ? null : Border.all(color: _hair),
        ),
        child: Text(m.text,
            style: TextStyle(
                fontSize: 15,
                height: 1.42,
                color: isUser ? Colors.white : _ink)),
      ),
    );
  }

  Widget _typing() {
    return Align(
      alignment: Alignment.centerLeft,
      child: Container(
        margin: const EdgeInsets.symmetric(vertical: 5),
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 13),
        decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(18),
          border: Border.all(color: _hair),
        ),
        child: SizedBox(
          width: 34,
          child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
            for (var i = 0; i < 3; i++)
              Container(width: 7, height: 7,
                  decoration: BoxDecoration(color: _muted.withValues(alpha: 0.5), shape: BoxShape.circle)),
          ]),
        ),
      ),
    );
  }

  Widget _composer(bool hasBank) {
    final bottomPad = MediaQuery.of(context).viewInsets.bottom;
    return Container(
      padding: EdgeInsets.fromLTRB(14, 8, 14, 8 + (bottomPad > 0 ? 8 : 0)),
      decoration: BoxDecoration(
        color: _card,
        border: Border(top: BorderSide(color: _hair)),
      ),
      child: SafeArea(
        top: false,
        child: Row(children: [
          Expanded(
            child: TextField(
              controller: _input,
              enabled: hasBank && !_sending,
              minLines: 1,
              maxLines: 4,
              textInputAction: TextInputAction.send,
              onSubmitted: _send,
              style: TextStyle(fontSize: 15, color: _ink),
              decoration: InputDecoration(
                hintText: hasBank ? tr('Klausk apie savo finansus…') : tr('Pirma prijunk banką'),
                hintStyle: TextStyle(color: _muted),
                filled: true,
                fillColor: _bg,
                contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(24), borderSide: BorderSide.none),
              ),
            ),
          ),
          const SizedBox(width: 8),
          GestureDetector(
            onTap: (hasBank && !_sending) ? () => _send(_input.text) : null,
            child: Container(
              width: 46, height: 46, alignment: Alignment.center,
              decoration: BoxDecoration(
                color: (hasBank && !_sending) ? _purple : _muted.withValues(alpha: 0.3),
                shape: BoxShape.circle,
              ),
              child: const Icon(Icons.arrow_upward_rounded, color: Colors.white, size: 22),
            ),
          ),
        ]),
      ),
    );
  }
}
